import React from 'react';
import styles from './cta-card.module.css';

export const CtaCard = ({ 
  text, 
  buttonText, 
  buttonHref, 
  buttonTarget,
  buttonRel,
  accentColor = 'cyan'
}) => {
  const accentStyles = {
    cyan: {
      beforeBg: 'linear-gradient(90deg, transparent, var(--color-accent-cyan), transparent)',
      borderHover: 'color-mix(in srgb, var(--color-accent-cyan) 45%, transparent)',
      shadowHover: `
        0 0 0 1px color-mix(in srgb, var(--color-accent-cyan) 15%, transparent),
        0 16px 48px -12px color-mix(in srgb, var(--color-accent-cyan) 25%, transparent),
        inset 0 0 40px color-mix(in srgb, var(--color-accent-cyan) 4%, transparent)
      `,
      buttonBg: 'color-mix(in srgb, var(--color-accent-cyan) 15%, transparent)',
      buttonBorder: 'color-mix(in srgb, var(--color-accent-cyan) 50%, transparent)',
      buttonColor: 'color-mix(in srgb, var(--color-accent-cyan) 30%, var(--color-white))',
      buttonBgHover: 'color-mix(in srgb, var(--color-accent-cyan) 28%, rgba(0, 0, 0, 0.4))',
      buttonBorderHover: 'var(--color-accent-cyan)',
      buttonShadowHover: `
        0 0 20px color-mix(in srgb, var(--color-accent-cyan) 30%, transparent),
        inset 0 0 12px color-mix(in srgb, var(--color-accent-cyan) 8%, transparent)
      `,
      cornerColor: 'var(--color-card-corner)',
    },
    pink: {
      beforeBg: 'linear-gradient(90deg, transparent, var(--color-accent-pink), transparent)',
      borderHover: 'color-mix(in srgb, var(--color-accent-pink) 45%, transparent)',
      shadowHover: `
        0 0 0 1px color-mix(in srgb, var(--color-accent-pink) 15%, transparent),
        0 16px 48px -12px color-mix(in srgb, var(--color-accent-pink) 25%, transparent),
        inset 0 0 40px color-mix(in srgb, var(--color-accent-pink) 4%, transparent)
      `,
      buttonBg: 'color-mix(in srgb, var(--color-accent-pink) 15%, transparent)',
      buttonBorder: 'color-mix(in srgb, var(--color-accent-pink) 50%, transparent)',
      buttonColor: 'color-mix(in srgb, var(--color-accent-pink) 30%, var(--color-white))',
      buttonBgHover: 'color-mix(in srgb, var(--color-accent-pink) 28%, rgba(0, 0, 0, 0.4))',
      buttonBorderHover: 'var(--color-accent-pink)',
      buttonShadowHover: `
        0 0 20px color-mix(in srgb, var(--color-accent-pink) 30%, transparent),
        inset 0 0 12px color-mix(in srgb, var(--color-accent-pink) 8%, transparent)
      `,
      cornerColor: 'var(--color-accent-pink)',
    },
    green: {
      beforeBg: 'linear-gradient(90deg, transparent, var(--color-accent-green), var(--color-accent-green), transparent)',
      borderHover: 'color-mix(in srgb, var(--color-accent-green) 45%, transparent)',
      shadowHover: `
        0 0 0 1px color-mix(in srgb, var(--color-accent-green) 15%, transparent),
        0 16px 48px -12px color-mix(in srgb, var(--color-accent-green) 25%, transparent),
        inset 0 0 40px color-mix(in srgb, var(--color-accent-green) 4%, transparent)
      `,
      buttonBg: 'color-mix(in srgb, var(--color-accent-green) 15%, transparent)',
      buttonBorder: 'color-mix(in srgb, var(--color-accent-green) 50%, transparent)',
      buttonColor: 'color-mix(in srgb, var(--color-accent-green) 30%, var(--color-white))',
      buttonBgHover: 'color-mix(in srgb, var(--color-accent-green) 28%, rgba(0, 0, 0, 0.4))',
      buttonBorderHover: 'var(--color-accent-green)',
      buttonShadowHover: `
        0 0 20px color-mix(in srgb, var(--color-accent-green) 30%, transparent),
        inset 0 0 12px color-mix(in srgb, var(--color-accent-green) 8%, transparent)
      `,
      cornerColor: 'var(--color-accent-green)',
    }
  };

  const a = accentStyles[accentColor] || accentStyles.cyan;

  const cardStyle = {
    '--cta-before-bg': a.beforeBg,
    '--cta-border-hover': a.borderHover,
    '--cta-shadow-hover': a.shadowHover,
    '--cta-button-bg': a.buttonBg,
    '--cta-button-border': a.buttonBorder,
    '--cta-button-color': a.buttonColor,
    '--cta-button-bg-hover': a.buttonBgHover,
    '--cta-button-border-hover': a.buttonBorderHover,
    '--cta-button-shadow-hover': a.buttonShadowHover,
    '--cta-corner-color': a.cornerColor,
  };

  const cardCornerTLStyle = {
    borderColor: a.cornerColor
  };
  const cardCornerBRStyle = {
    borderColor: a.cornerColor
  };

  return (
    <article className={styles.ctaCard} style={cardStyle}>
      <div className={styles.cardScanline} aria-hidden="true" />
      <div className={styles.cardCornerTL} style={cardCornerTLStyle} aria-hidden="true" />
      <div className={styles.cardCornerBR} style={cardCornerBRStyle} aria-hidden="true" />
      
      <div className={styles.ctaContent}>
        <p className={styles.ctaText}>{text}</p>
        <a 
          href={buttonHref} 
          target={buttonTarget}
          rel={buttonRel}
          className={styles.ctaButton}
        >
          <span className={styles.ctaButtonText}>{buttonText}</span>
          <span className={styles.ctaButtonArrow} aria-hidden="true">→</span>
        </a>
      </div>
    </article>
  );
};